// ---- utilidades compartidas (se copian dentro de los nodos Code que las usan) ----
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// Fecha larga en español a partir de 'YYYY-MM-DD' (ya es la fecha LOCAL: la calcula la base de datos).
const fechaLarga = (ymd) => new Intl.DateTimeFormat('es-ES', {
  timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
}).format(new Date(ymd + 'T12:00:00Z'));

// --- .ics (RFC 5545): horas en UTC, así el cambio de hora no afecta ---
const icsEsc = (s) => String(s ?? '').replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
const icsFold = (line) => {                       // líneas de máx. 75 octetos
  let out = '', cur = '', bytes = 0, first = true;
  for (const ch of line) {
    const b = Buffer.byteLength(ch);
    if (bytes + b > (first ? 75 : 74)) { out += cur + '\r\n '; cur = ''; bytes = 0; first = false; }
    cur += ch; bytes += b;
  }
  return out + cur;
};
const icsTime = (iso) => iso.replace(/[-:]/g, '').replace(/\.\d+/, '');   // 2026-11-09T09:00:00Z -> 20261109T090000Z
// sequence: versión del evento (la lleva la base de datos: 0 reserva, +1 por cada cambio o cancelación).
// Sin indicarla se usa la de la Fase 1: 0 (confirmado) / 1 (cancelado).
function buildIcs({ uid, start, end, summary, description, url, cancelled, sequence }) {
  const now = new Date().toISOString().slice(0, 19) + 'Z';
  const lines = [
    'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Turnos//n8n//ES', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
    'BEGIN:VEVENT',
    `UID:${uid}@turnos`,
    `DTSTAMP:${icsTime(now)}`,
    `DTSTART:${icsTime(start)}`,
    `DTEND:${icsTime(end)}`,
    `SUMMARY:${icsEsc(summary)}`,
    `DESCRIPTION:${icsEsc(description)}`,
    url ? `URL:${url}` : null,
    `STATUS:${cancelled ? 'CANCELLED' : 'CONFIRMED'}`,
    `SEQUENCE:${sequence ?? (cancelled ? 1 : 0)}`,
    ...(cancelled ? [] : ['BEGIN:VALARM', 'TRIGGER:-PT1H', 'ACTION:DISPLAY', 'DESCRIPTION:Recordatorio de turno', 'END:VALARM']),
    'END:VEVENT', 'END:VCALENDAR',
  ].filter(Boolean);
  return lines.map(icsFold).join('\r\n') + '\r\n';
}

// --- enlaces de gestión: <url del formulario>?codigo=<código secreto> ---
const enlaceCon = (base, code) => {
  const b = String(base ?? '');
  return b ? b + (b.includes('?') ? '&' : '?') + 'codigo=' + code : '';
};
const dmy = (ymd) => String(ymd).split('-').reverse().join('/');          // 2026-11-09 -> 09/11/2026

// --- avisos a quien atiende (inmediatos y resumen): misma plantilla sencilla ---
// filas: [[etiqueta, valor], ...]  ->  { text, html }
function plantillaAviso(titulo, filas) {
  const text = [titulo, '', ...filas.map(([k, v]) => `${k}: ${v}`)].join('\n');
  const html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:auto;color:#1f2937">
<h2 style="margin:0 0 12px">${esc(titulo)}</h2>
<table style="border-collapse:collapse">${filas.map(([k, v]) => `<tr><td style="padding:4px 14px 4px 0;color:#6b7280;vertical-align:top">${esc(k)}</td><td><b>${esc(v)}</b></td></tr>`).join('')}</table></div>`;
  return { text, html };
}
// Destinatario del aviso: staff_email (o, si está vacío, admin_email: lo resuelve get_config); nunca queda sin destino.
const destinoPersonal = (cfg, conf) => cfg.staff_email || cfg.admin_email || conf.from_email;

// Resumen diario para quien atiende: turnos confirmados de HOY (día local), ordenados por hora.
// Sin turnos: aviso breve (a menos que settings.daily_summary_send_empty = false; entonces la base
// de datos ni siquiera marca "due+send" y este nodo no llega a ejecutarse).
const s = $input.first().json;                          // claim_daily_summary: { due:true, send:true, local_date, count, bookings:[...] }
const cfg = $('Cargar parámetros').first().json;
const conf = $('Configuración').first().json;

const fecha = fechaLarga(s.local_date);
const lista = s.bookings ?? [];
const asunto = lista.length
  ? `[Turnos] Agenda de hoy · ${dmy(s.local_date)} · ${lista.length} ${lista.length === 1 ? 'turno' : 'turnos'}`
  : `[Turnos] Agenda de hoy · ${dmy(s.local_date)} · sin turnos`;

let text, html;
if (!lista.length) {
  text = `Buenos días,\n\nHoy, ${fecha}, no hay ningún turno confirmado.`;
  html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:560px;margin:auto;color:#1f2937"><h2 style="margin:0 0 12px">Agenda de hoy</h2><p>Hoy, ${esc(fecha)}, no hay ningún turno confirmado.</p></div>`;
} else {
  text = [`Buenos días,`, '', `Turnos confirmados de hoy, ${fecha} (hora de ${s.timezone}):`, '',
    ...lista.map((b) => `${b.local_time}  ${b.service_name} · ${b.customer_name} · ${b.customer_phone} · ${b.customer_email}`)].join('\n');
  html = `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:auto;color:#1f2937">
<h2 style="margin:0 0 4px">Agenda de hoy</h2>
<p style="margin:0 0 12px;color:#6b7280">${esc(fecha)} · ${lista.length} ${lista.length === 1 ? 'turno confirmado' : 'turnos confirmados'} (hora de ${esc(s.timezone)})</p>
<table style="border-collapse:collapse;width:100%">
<tr style="text-align:left;color:#6b7280"><th style="padding:6px 10px 6px 0">Hora</th><th style="padding:6px 10px 6px 0">Servicio</th><th style="padding:6px 10px 6px 0">Nombre</th><th style="padding:6px 10px 6px 0">Teléfono</th><th style="padding:6px 0">Correo</th></tr>
${lista.map((b) => `<tr style="border-top:1px solid #e5e7eb"><td style="padding:6px 10px 6px 0"><b>${esc(b.local_time)}</b></td><td style="padding:6px 10px 6px 0">${esc(b.service_name)}</td><td style="padding:6px 10px 6px 0">${esc(b.customer_name)}</td><td style="padding:6px 10px 6px 0">${esc(b.customer_phone)}</td><td style="padding:6px 0">${esc(b.customer_email)}</td></tr>`).join('\n')}
</table></div>`;
}

return [{ json: { day: s.day, from: conf.from_email, to: destinoPersonal(cfg, conf), subject: asunto, text, html, count: lista.length } }];
